 * page with no reachable nav. WCAG: focus trap while open, Escape to close, focus
 * restored to the trigger on close, aria-expanded/aria-controls wired, backdrop
 * click + link click both dismiss.
 *
 * Portal-mounted to document.body so the header's backdrop-filter and view-transition
 * styles don't trap the fixed backdrop inside the 3.5rem header height.
 */
export function MobileNav({ links }: { links: NavLink[] }) {
  const [open, setOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const { view } = useView();
  const prevView = useRef(view);

  // Close the drawer if the view changes (e.g. via ViewSwitcher in the drawer).
  useEffect(() => {
    if (prevView.current !== view) {
      setOpen(false);
      prevView.current = view;
    }
  }, [view]);

  // Lock background scroll while the drawer is open.
  useEffect(() => {
    if (!open) return;
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = prevOverflow;
    };
  }, [open]);

  // Dismiss if viewport expands to desktop.
  useEffect(() => {
    if (!open) return;
    const onResize = () => {
      if (window.innerWidth >= 1024) setOpen(false);
    };
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, [open]);

  // Close on Escape and trap focus within the panel while open.
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        setOpen(false);
        return;
      }
      if (e.key !== "Tab") return;
      const focusables = panelRef.current?.querySelectorAll<HTMLElement>(
        'a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])',
      );
      if (!focusables || focusables.length === 0) return;
      const first = focusables[0];
      const last = focusables[focusables.length - 1];
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
