cat << 'EOF' > /tmp/verify_audit.js
const { chromium } = require('@playwright/test');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch();
  const dir = '/tmp/verification_screenshots';
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

  const results = [];

  // Helper to test a viewport
  async function testMobile(width, height, label) {
    console.log(`\n=== Testing ${label} (${width}x${height}) ===`);
    const context = await browser.newContext({
      viewport: { width, height },
      deviceScaleFactor: 2,
    });
    const page = await context.newPage();

    // 1. /about scrolled to bottom
    console.log(`[${label}] Testing /about bottom...`);
    await page.goto('http://localhost:3000/about', { waitUntil: 'networkidle' });
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
    await page.waitForTimeout(500);

    const askBtn = await page.locator('button[aria-label="Ask my portfolio"]').boundingBox();
    const cmdkBtn = await page.locator('button[aria-label="Open command palette"]').boundingBox();
    const subscribeLink = await page.locator('footer a:has-text("Subscribe")').boundingBox();
    const copyright = await page.locator('footer span:has-text("Sairam Ugge")').first().boundingBox();

    console.log('Ask button:', askBtn);
    console.log('⌘K button:', cmdkBtn);
    console.log('Subscribe link:', subscribeLink);
    console.log('Copyright span:', copyright);

    const askOverlap = askBtn && copyright && (askBtn.y < copyright.y + copyright.height && askBtn.y + askBtn.height > copyright.y);
    const cmdkOverlap = cmdkBtn && subscribeLink && (cmdkBtn.y < subscribeLink.y + subscribeLink.height && cmdkBtn.y + cmdkBtn.height > subscribeLink.y);

    console.log(`Ask button overlaps copyright? ${askOverlap}`);
    console.log(`⌘K button overlaps Subscribe link? ${cmdkOverlap}`);
    console.log(`Subscribe link is above ⌘K button? ${subscribeLink.y + subscribeLink.height < cmdkBtn.y} (gap: ${cmdkBtn.y - (subscribeLink.y + subscribeLink.height)}px)`);

    await page.screenshot({ path: `${dir}/${label}_about_bottom.png` });

    // 2. Mobile menu open & tap outside
    console.log(`[${label}] Testing mobile menu...`);
    await page.goto('http://localhost:3000/about', { waitUntil: 'networkidle' });
    const menuBtn = page.locator('button[aria-label="Open menu"]');
    await menuBtn.click();
    await page.waitForTimeout(300);

    const panel = page.locator('#mobile-nav-panel');
    const panelBox = await panel.boundingBox();
    const backdrop = page.locator('div[aria-hidden="true"].backdrop-blur-sm');
    const backdropBox = await backdrop.boundingBox();

    console.log('Menu panel box:', panelBox);
    console.log('Backdrop box:', backdropBox);

    const backdropCoversPage = backdropBox && backdropBox.height >= height - 56 && backdropBox.y >= 50;
    console.log(`Backdrop covers rest of page (${height - 56}px)? ${backdropCoversPage} (actual height: ${backdropBox?.height}px)`);

    await page.screenshot({ path: `${dir}/${label}_menu_open.png` });

    // Tap outside menu (on the backdrop below the panel)
    const tapY = Math.min(height - 50, panelBox.y + panelBox.height + 60);
    console.log(`Tapping outside menu at x: ${width / 2}, y: ${tapY}...`);
    await page.mouse.click(width / 2, tapY);
    await page.waitForTimeout(400);

    const isPanelVisibleAfterTap = await panel.isVisible().catch(() => false);
    console.log(`Is menu panel closed after tapping outside? ${!isPanelVisibleAfterTap}`);

    // 3. Chat view (/?view=chat)
    console.log(`[${label}] Testing chat view (/?view=chat)...`);
    await page.goto('http://localhost:3000/?view=chat', { waitUntil: 'networkidle' });
    await page.waitForSelector('main', { timeout: 10000 });
    // allow view hydration
    await page.waitForTimeout(1000);

    const aiConcierge = await page.locator('p:has-text("AI Concierge")').boundingBox();
    const talkBtn = await page.locator('button:has-text("Talk")').boundingBox().catch(() => null);
    const backBtn = await page.locator('button:has-text("Back to Classic")').boundingBox();
    const resumeLink = await page.locator('a:has-text("Résumé")').first().boundingBox();
    const caption = await page.locator('p:has-text("Grounded in real work")').boundingBox();
    const chatCmdkBtn = await page.locator('button[aria-label="Open command palette"]').boundingBox();

    console.log('Back button:', backBtn);
    console.log('Résumé link:', resumeLink);
    console.log('Talk button:', talkBtn);
    console.log('AI Concierge:', aiConcierge);
    console.log('Caption ("Grounded in real work..."):', caption);
    console.log('Chat ⌘K button:', chatCmdkBtn);

    const aiConciergeCutOff = aiConcierge && (aiConcierge.x + aiConcierge.width > width);
    console.log(`Is AI Concierge cut off at right edge? ${aiConciergeCutOff} (right edge at ${aiConcierge?.x + aiConcierge?.width}px, viewport width: ${width}px)`);

    const captionOverlap = chatCmdkBtn && caption && (
      chatCmdkBtn.y < caption.y + caption.height &&
      chatCmdkBtn.y + chatCmdkBtn.height > caption.y &&
      chatCmdkBtn.x < caption.x + caption.width &&
      chatCmdkBtn.x + chatCmdkBtn.width > caption.x
    );
    console.log(`Does ⌘K button overlap caption? ${captionOverlap}`);
    console.log(`Caption is safely above ⌘K button? ${caption.y + caption.height <= chatCmdkBtn.y} (caption bottom: ${caption?.y + caption?.height}px, ⌘K top: ${chatCmdkBtn?.y}px)`);

    await page.screenshot({ path: `${dir}/${label}_chat_view.png` });

    await context.close();

    return {
      label,
      askOverlap,
      cmdkOverlap,
      backdropCoversPage,
      menuClosedAfterTap: !isPanelVisibleAfterTap,
      aiConciergeCutOff,
      captionOverlap,
    };
  }

  // Desktop test
  async function testDesktop() {
    console.log('\n=== Testing Desktop (1280x800) ===');
    const context = await browser.newContext({
      viewport: { width: 1280, height: 800 },
      deviceScaleFactor: 2,
    });
    const page = await context.newPage();

    console.log('[Desktop] Testing chat view...');
    await page.goto('http://localhost:3000/?view=chat', { waitUntil: 'networkidle' });
    await page.waitForSelector('main', { timeout: 10000 });
    await page.waitForTimeout(1000);

    const backBtn = await page.locator('button:has-text("Back to Classic")').boundingBox();
    const aiConcierge = await page.locator('p:has-text("AI Concierge")').boundingBox();
    const chatCmdkBtn = await page.locator('button[aria-label="Open command palette"]').boundingBox();

    console.log('Desktop Back button:', backBtn);
    console.log('Desktop AI Concierge:', aiConcierge);
    console.log('Desktop ⌘K button:', chatCmdkBtn);

    // On desktop, Back button and AI Concierge should be on the same horizontal row (same y within 5px)
    const sameRow = Math.abs(backBtn.y - aiConcierge.y) < 6;
    console.log(`Back button and AI Concierge on the same row on desktop? ${sameRow} (back Y: ${backBtn.y}, AI Y: ${aiConcierge.y})`);

    await page.screenshot({ path: `${dir}/desktop_chat_view.png` });

    console.log('[Desktop] Testing /about bottom...');
    await page.goto('http://localhost:3000/about', { waitUntil: 'networkidle' });
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
    await page.waitForTimeout(500);

    await page.screenshot({ path: `${dir}/desktop_about_bottom.png` });

    await context.close();
    return { sameRow };
  }

  const res390 = await testMobile(390, 844, '390px');
  const res320 = await testMobile(320, 568, '320px');
  const resDesktop = await testDesktop();

  console.log('\n================ SUMMARY ================');
  console.log('390px results:', res390);
  console.log('320px results:', res320);
  console.log('Desktop results:', resDesktop);

  await browser.close();
})();
EOF
