    const resumeLink = await page.locator('a:has-text("Résumé")').first().boundingBox();
    const caption = await page.locator('p:has-text("Grounded in real work")').boundingBox();
    const chatCmdkBtn = await page.locator('button[aria-label="Open command palette"]').boundingBox();

    console.log('Back button:', backBtn);
    console.log('Résumé link:', resumeLink);
    console.log('Talk button:', talkBtn);
    console.log('AI Concierge:', aiConcierge);
    console.log('Caption ("Grounded in real work..."):', caption);
    console.log('Chat ⌘K button:', chatCmdkBtn);

    const aiConciergeCutOff = aiConcierge && (aiConcierge.x + aiConcierge.width > width);
    console.log(`Is AI Concierge cut off at right edge? ${aiConciergeCutOff} (right edge at ${aiConcierge?.x + aiConcierge?.width}px, viewport width: ${width}px)`);

    const captionOverlap = chatCmdkBtn && caption && (
      chatCmdkBtn.y < caption.y + caption.height &&
      chatCmdkBtn.y + chatCmdkBtn.height > caption.y &&
      chatCmdkBtn.x < caption.x + caption.width &&
      chatCmdkBtn.x + chatCmdkBtn.width > caption.x
    );
    console.log(`Does ⌘K button overlap caption? ${captionOverlap}`);
    console.log(`Caption is safely above ⌘K button? ${caption.y + caption.height <= chatCmdkBtn.y} (caption bottom: ${caption?.y + caption?.height}px, ⌘K top: ${chatCmdkBtn?.y}px, clearance: ${chatCmdkBtn?.y - (caption?.y + caption?.height)}px)`);

    await page.screenshot({ path: `${dir}/${label}_chat_view.png` });

    await context.close();

    return {
      label,
      askOverlap,
      cmdkOverlap,
      backdropCoversPage,
      menuClosedAfterTap: !isPanelVisibleAfterTap,
      aiConciergeCutOff,
      captionOverlap,
      captionClearance: chatCmdkBtn?.y - (caption?.y + caption?.height),
    };
  }

  // Desktop test
  async function testDesktop() {
    console.log('\n=== Testing Desktop (1280x800) ===');
    const context = await browser.newContext({
      viewport: { width: 1280, height: 800 },
      deviceScaleFactor: 2,
    });
    const page = await context.newPage();

    console.log('[Desktop] Testing chat view...');
    await page.goto('http://localhost:3000/?view=chat', { waitUntil: 'networkidle' });
    const aiConciergeLocator = page.locator('p:has-text("AI Concierge")');
    await aiConciergeLocator.waitFor({ timeout: 15000 });
    await page.waitForTimeout(1000);

    const backBtn = await page.locator('button:has-text("Back to Classic")').boundingBox();
    const aiConcierge = await aiConciergeLocator.boundingBox();
    const chatCmdkBtn = await page.locator('button[aria-label="Open command palette"]').boundingBox();

    console.log('Desktop Back button:', backBtn);
    console.log('Desktop AI Concierge:', aiConcierge);
    console.log('Desktop ⌘K button:', chatCmdkBtn);

    // On desktop, Back button and AI Concierge should be on the same horizontal row (same y within 5px)
    const sameRow = Math.abs(backBtn.y - aiConcierge.y) < 6;
    console.log(`Back button and AI Concierge on the same row on desktop? ${sameRow} (back Y: ${backBtn.y}, AI Y: ${aiConcierge.y})`);

    await page.screenshot({ path: `${dir}/desktop_chat_view.png` });

    console.log('[Desktop] Testing /about bottom...');
    await page.goto('http://localhost:3000/about', { waitUntil: 'networkidle' });
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
    await page.waitForTimeout(500);

    await page.screenshot({ path: `${dir}/desktop_about_bottom.png` });

    await context.close();
    return { sameRow };
  }

  const res390 = await testMobile(390, 844, '390px');
  const res320 = await testMobile(320, 568, '320px');
  const resDesktop = await testDesktop();

  console.log('\n================ SUMMARY ================');
  console.log('390px results:', res390);
  console.log('320px results:', res320);
  console.log('Desktop results:', resDesktop);

  await browser.close();
})();
